#include <stdio.h>
#include <string.h>

typedef struct {
    char name[21];
    int smile;
    int pure;
    int cool;
} Unit;

int main() {
    int n;
    scanf("%d", &n);

    Unit units[50];
    int dosanko_idx = -1;

    for (int i = 0; i < n; i++) {
        scanf("%s %d %d %d", units[i].name, &units[i].smile, &units[i].pure, &units[i].cool);
        if (strcmp(units[i].name, "Dosanko") == 0) {
            dosanko_idx = i;
        }
    }

    int dosanko_total = units[dosanko_idx].smile + units[dosanko_idx].pure + units[dosanko_idx].cool;
    int min_increase = 1000000;

    // Try increasing each stat
    for (int stat = 0; stat < 3; stat++) {
        int current_val;
        if (stat == 0) current_val = units[dosanko_idx].smile;
        else if (stat == 1) current_val = units[dosanko_idx].pure;
        else current_val = units[dosanko_idx].cool;

        // Try different increases
        for (int increase = 0; increase <= 100; increase++) {
            int new_total = dosanko_total + increase;

            // Count how many have strictly higher total
            int higher_count = 0;
            for (int i = 0; i < n; i++) {
                if (i == dosanko_idx) continue;
                int other_total = units[i].smile + units[i].pure + units[i].cool;
                if (other_total > new_total) {
                    higher_count++;
                }
            }

            // If at most 7 have higher score, we're at least 8th
            if (higher_count <= 7) {
                if (increase < min_increase) {
                    min_increase = increase;
                }
                break;
            }
        }
    }

    printf("%d\n", min_increase);

    return 0;
}

