    int rank = 1;
    for (int i = 0; i < 9; i++) {
        if (vals[i][cat] > v) rank++;
    }
    return 10 - rank;
}

int total_score(int idx) {
    return get_points(0,idx) + get_points(1,idx) + get_points(2,idx);
}

int overall_rank(int idx) {
    int my_score = total_score(idx);
    int rank = 1;
    for (int i = 0; i < 9; i++) {
        if (total_score(i) > my_score) rank++;
    }
    return rank;
}

