typedef long long ll;

typedef struct {
    ll s, p, c;
} Idol;

static int better(ll ts, ll tp, ll tc, ll sum,
                  ll os, ll op, ll oc, ll osum) {
    if (sum != osum) return sum > osum;
    if (ts != os) return ts > os;
    if (tp != op) return tp > op;
    return tc > oc;
}

static int rank_of_target(Idol a[9], ll ts, ll tp, ll tc) {
    ll tsum = ts + tp + tc;
    int rank = 1;
    for (int i = 0; i < 8; i++) {
        ll os = a[i].s, op = a[i].p, oc = a[i].c;
        ll osum = os + op + oc;
        if (better(os, op, oc, osum, ts, tp, tc, tsum)) rank++;
    }
    return rank;
}

int main(void) {
    Idol a[9];
    for (int i = 0; i < 9; i++) {
        if (scanf("%lld %lld %lld", &a[i].s, &a[i].p, &a[i].c) != 3) return 0;
    }

    /* Assume the 9th idol is Dosanko Snow */
    ll s = a[8].s, p = a[8].p, c = a[8].c;

    if (rank_of_target(a, s, p, c) <= 8) {
        printf("0\n");
        return 0;
    }

    ll ans = (1LL << 62);

    /* Increase Smile only */
    {
        ll low = 0, high = 1;
        while (rank_of_target(a, s + high, p, c) > 8) high <<= 1;
        while (low < high) {
            ll mid = low + (high - low) / 2;
            if (rank_of_target(a, s + mid, p, c) <= 8) high = mid;
            else low = mid + 1;
        }
        if (low < ans) ans = low;
    }

    /* Increase Pure only */
    {
        ll low = 0, high = 1;
        while (rank_of_target(a, s, p + high, c) > 8) high <<= 1;
        while (low < high) {
            ll mid = low + (high - low) / 2;
            if (rank_of_target(a, s, p + mid, c) <= 8) high = mid;
            else low = mid + 1;
        }
        if (low < ans) ans = low;
    }

    /* Increase Cool only */
    {
        ll low = 0, high = 1;
        while (rank_of_target(a, s, p, c + high) > 8) high <<= 1;
        while (low < high) {
            ll mid = low + (high - low) / 2;
            if (rank_of_target(a, s, p, c + mid) <= 8) high = mid;
            else low = mid + 1;
        }
        if (low < ans) ans = low;
    }

    printf("%lld\n", ans);
    return 0;
}

