public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] smile = new int[n];
        int[] pure = new int[n];
        int[] cool = new int[n];
        for (int i = 0; i < n; i++) {
            smile[i] = sc.nextInt();
            pure[i] = sc.nextInt();
            cool[i] = sc.nextInt();
        }
        // Dosanko Snow is last (index n-1)
        int s0 = smile[n-1];
        int p0 = pure[n-1];
        int c0 = cool[n-1];

        // Precompute total scores for all except Dosanko Snow
        int[] totals = new int[n-1];
        for (int i = 0; i < n-1; i++) {
            totals[i] = smile[i] + pure[i] + cool[i];
        }
        Arrays.sort(totals);

        long lo = 0, hi = 3000; // each stat max 1000, so increase max 3000
        long ans = -1;
        while (lo <= hi) {
            long mid = (lo + hi) / 2;
            if (canAvoid9th(s0, p0, c0, mid, totals)) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        System.out.println(ans);
    }

    static boolean canAvoid9th(int s0, int p0, int c0, long add, int[] totals) {
        // Try adding to Smile
        int newS = s0 + (int) Math.min(add, 1000 - s0);
        int newP = p0;
        int newC = c0;
        if (countBetter(newS + newP + newC, totals) <= 7) return true;

        // Try adding to Pure
        newS = s0;
        newP = p0 + (int) Math.min(add, 1000 - p0);
        newC = c0;
        if (countBetter(newS + newP + newC, totals) <= 7) return true;

        // Try adding to Cool
        newS = s0;
        newP = p0;
        newC = c0 + (int) Math.min(add, 1000 - c0);
        if (countBetter(newS + newP + newC, totals) <= 7) return true;

        return false;
    }

    static int countBetter(int myScore, int[] totals) {
        // Binary search for number of scores strictly greater than myScore
        int lo = 0, hi = totals.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (totals[mid] > myScore) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return totals.length - lo; // number strictly greater
    }
}

