public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 9;
        int[][] units = new int[n][3];
        for (int i = 0; i < n; i++) {
            units[i][0] = sc.nextInt();
            units[i][1] = sc.nextInt();
            units[i][2] = sc.nextInt();
        }

        // Dosanko Snow is the last unit (index 8)
        int myIdx = n - 1;

        // Check if already not 9th
        if (getRank(units, myIdx) <= 8) {
            System.out.println(0);
            return;
        }

        int ans = Integer.MAX_VALUE;
        for (int attr = 0; attr < 3; attr++) {
            // Binary search for minimum increase
            int lo = 0, hi = 1000000;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                units[myIdx][attr] += mid;
                int rank = getRank(units, myIdx);
                units[myIdx][attr] -= mid;
                if (rank <= 8) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            ans = Math.min(ans, lo);
        }

        System.out.println(ans);
    }

    static int getRank(int[][] units, int myIdx) {
        int n = units.length;
        int[] points = new int[n];

        for (int attr = 0; attr < 3; attr++) {
            // Sort by this attribute descending to assign points
            Integer[] order = new Integer[n];
            for (int i = 0; i < n; i++) order[i] = i;
            final int a = attr;
            Arrays.sort(order, (x, y) -> units[y][a] - units[x][a]);

            for (int rank = 0; rank < n; rank++) {
                points[order[rank]] += (n - rank);
            }
        }

        int myPoints = points[myIdx];
        int myRank = 1;
        for (int i = 0; i < n; i++) {
            if (i != myIdx && points[i] > myPoints) {
                myRank++;
            }
        }
        return myRank;
    }
}

