import java.util.*;

public class Main {
    static class Idol {
        long s, p, c;
        long total() { return s + p + c; }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = 9; // fixed by statement: 9 participants
        Idol[] a = new Idol[n];
        for (int i = 0; i < n; i++) {
            a[i] = new Idol();
            a[i].s = fs.nextLong();
            a[i].p = fs.nextLong();
            a[i].c = fs.nextLong();
        }

        // Dosanko Snow is the 9th contestant
        Idol me = a[8];
        long mySum = me.total();

        // To avoid 9th place, it is enough to tie or exceed at least one other contestant's total.
        // Minimum increase needed in one category equals:
        // max(0, min_i(otherSum_i - mySum)) over the 8 others, but if strictly below all,
        // need to reach the smallest other total, i.e. difference.
        // Since tie for 8th is acceptable, required increase is:
        // min_i max(0, otherSum_i - mySum)
        long ans = Long.MAX_VALUE;
        for (int i = 0; i < 8; i++) {
            long diff = a[i].total() - mySum;
            if (diff < 0) diff = 0;
            ans = Math.min(ans, diff);
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

