using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<string> names(N);
    vector<array<int, 3>> stats(N);
    for (int i = 0; i < N; i++) {
        cin >> names[i] >> stats[i][0] >> stats[i][1] >> stats[i][2];
    }

    // Find index of "Dosanko Snow"
    int idx = -1;
    for (int i = 0; i < N; i++) {
        if (names[i] == "Dosanko Snow") {
            idx = i;
            break;
        }
    }

    // Compute points per category:
    // For each category, sort indices by stat descending, assign points (N, N-1, ..., 1)
    vector<vector<int>> points(N, vector<int>(3));
    for (int cat = 0; cat < 3; cat++) {
        vector<pair<int,int>> v;
        for (int i = 0; i < N; i++) {
            v.push_back({stats[i][cat], i});
        }
        sort(v.begin(), v.end(), greater<>());
        int curPoints = N;
        for (int i = 0; i < N; i++) {
            int j = i;
            while (j < N && v[j].first == v[i].first) {
                points[v[j].second][cat] = curPoints;
                j++;
            }
            // adjust points for tied ranks: all get the same points = N - i
            int assignedPoints = N - i;
            for (int k = i; k < j; k++) {
                points[v[k].second][cat] = assignedPoints;
            }
            i = j - 1;
            curPoints = assignedPoints - 1;
        }
    }

    // Total scores
    vector<int> total(N);
    for (int i = 0; i < N; i++) {
        total[i] = points[i][0] + points[i][1] + points[i][2];
    }

    // Find 8th place score (0-index: position 7)
    vector<int> sortedTotal = total;
    sort(sortedTotal.begin(), sortedTotal.end(), greater<>());
    int targetScore = sortedTotal[7]; // 8th place score

    int ans = INT_MAX;
    int myTotal = total[idx];

    // If already >= target, answer is 0
    if (myTotal >= targetScore) {
        cout << 0 << "\n";
        return 0;
    }

    // Try increasing each stat
    for (int cat = 0; cat < 3; cat++) {
        int curStat = stats[idx][cat];
        // We can increase up to 100 (since max stat is 100)
        for (int inc = 1; inc <= 100 - curStat; inc++) {
            int newStat = curStat + inc;
            // Compute new rank points in this category
            int rankPoints = 0;
            // Count how many have stat > newStat, and how many have stat == newStat
            int greater = 0, equal = 0;
            for (int i = 0; i < N; i++) {
                if (i == idx) continue;
                if (stats[i][cat] > newStat) greater++;
                else if (stats[i][cat] == newStat) equal++;
            }
            // rank = greater+1
            int newRank = greater + 1;
            // points = N - (newRank-1) = N - greater
            rankPoints = N - greater;

            int newTotal = myTotal - points[idx][cat] + rankPoints;
            if (newTotal >= targetScore) {
                ans = min(ans, inc);
                break; // no need larger inc for this cat
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

