using namespace std;

int calcScore(vector<array<int,3>>& units, int idx) {
    int score = 0;
    for (int c = 0; c < 3; c++) {
        int rank = 1;
        for (int i = 0; i < 9; i++) {
            if (units[i][c] > units[idx][c]) rank++;
        }
        score += (10 - rank);
    }
    return score;
}

int main() {
    vector<array<int,3>> units(9);
    for (int i = 0; i < 9; i++)
        cin >> units[i][0] >> units[i][1] >> units[i][2];

    // Try each attribute
    int ans = INT_MAX;
    for (int attr = 0; attr < 3; attr++) {
        for (int add = 0; add <= 100000; add++) {
            units[8][attr] += (add > 0 ? 1 : 0);
            // recalculate
            int myScore = calcScore(units, 8);
            // check rank of Dosanko Snow
            int myRank = 1;
            for (int i = 0; i < 8; i++) {
                if (calcScore(units, i) > myScore) myRank++;
            }
            if (myRank <= 8) {
                ans = min(ans, add);
                break;
            }
        }
        // reset
        units[8][attr] = /* original */ 0; // need to track original
    }
}

