struct Idol {
    long long s, p, c;
    long long total() const { return s + p + c; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Idol> a(9);
    for (int i = 0; i < 9; ++i) {
        cin >> a[i].s >> a[i].p >> a[i].c;
    }

    // We assume the 9th input is Dosanko Snow.
    long long othersMax = 0;
    for (int i = 0; i < 8; ++i) {
        othersMax = max(othersMax, a[i].total());
    }

    long long cur = a[8].total();

    // To avoid 9th place, it is enough to tie or exceed the current 8th place total.
    // Since there are only 9 contestants, being strictly below all 8 others means 9th.
    // Therefore minimum needed increase is:
    long long ans = max(0LL, othersMax - cur);

    cout << ans << '\n';
    return 0;
}
